// ─── تجمیع اخبار + حذف تکراری‌ها + تاریخ شمسی (الگوریتم jalaali) ───
const MAX_CHARS = 12000;
const MAX_ITEMS = 50;

// ─── تبدیل میلادی به شمسی: پیاده‌سازی الگوریتم jalaali-js ───
function div(a, b) { return ~~(a / b); }
function mod(a, b) { return a - ~~(a / b) * b; }

function jalCal(jy) {
  const breaks = [-61, 9, 38, 199, 426, 686, 756, 818, 1111, 1181, 1210, 1635, 2060, 2097, 2192, 2262, 2324, 2394, 2456, 3178];
  const bl = breaks.length;
  const gy = jy + 621;
  let leapJ = -14;
  let jp = breaks[0];
  let jump = 0;
  for (let i = 1; i < bl; i += 1) {
    const jm = breaks[i];
    jump = jm - jp;
    if (jy < jm) break;
    leapJ = leapJ + div(jump, 33) * 8 + div(mod(jump, 33), 4);
    jp = jm;
  }
  let n = jy - jp;
  leapJ = leapJ + div(n, 33) * 8 + div(mod(n, 33) + 3, 4);
  if (mod(jump, 33) === 4 && jump - n === 4) leapJ += 1;
  const leapG = div(gy, 4) - div((div(gy, 100) + 1) * 3, 4) - 150;
  const march = 20 + leapJ - leapG;
  if (jump - n < 6) n = n - jump + div(jump + 4, 33) * 33;
  let leap = mod(mod(n + 1, 33) - 1, 4);
  if (leap === -1) leap = 4;
  return { leap, gy, march };
}

function g2d(gy, gm, gd) {
  let d = div((gy + div(gm - 8, 6) + 100100) * 1461, 4) + div(153 * mod(gm + 9, 12) + 2, 5) + gd - 34840408;
  d = d - div(div(gy + 100100 + div(gm - 8, 6), 100) * 3, 4) + 752;
  return d;
}

function d2j(jdn) {
  const gy = jyFromJdn(jdn);
  let jy = gy - 621;
  const r = jalCal(jy);
  const jdn1f = g2d(gy, 3, r.march);
  let k = jdn - jdn1f;
  if (k >= 0) {
    if (k <= 185) return { jy, jm: 1 + div(k, 31), jd: mod(k, 31) + 1 };
    k -= 186;
  } else {
    jy -= 1;
    k += 179;
    if (r.leap === 1) k += 1;
  }
  return { jy, jm: 7 + div(k, 30), jd: mod(k, 30) + 1 };
}

function jyFromJdn(jdn) {
  let j = 4 * jdn + 139361631;
  j = j + div(div(4 * jdn + 183187720, 146097) * 3, 4) * 4 - 3908;
  const i = div(mod(j, 1461), 4) * 5 + 308;
  const gm = mod(div(i, 153), 12) + 1;
  return div(j, 1461) - 100100 + div(8 - gm, 6);
}

function toJalali(gy, gm, gd) {
  return d2j(g2d(gy, gm, gd));
}

// ─── زمان تهران (UTC+3:30) و قالب‌بندی شمسی ───
const toFa = (n) => String(n).replace(/\d/g, (d) => '۰۱۲۳۴۵۶۷۸۹'[d]);
const pad2 = (n) => (n < 10 ? '0' + n : String(n));

// ایران از سال ۱۴۰۱ ساعت تابستانی ندارد و همیشه UTC+3:30 است
const tehran = new Date(Date.now() + 3.5 * 60 * 60 * 1000);
const j = toJalali(tehran.getUTCFullYear(), tehran.getUTCMonth() + 1, tehran.getUTCDate());
const jMonths = ['فروردین', 'اردیبهشت', 'خرداد', 'تیر', 'مرداد', 'شهریور', 'مهر', 'آبان', 'آذر', 'دی', 'بهمن', 'اسفند'];
// getUTCDay: 0=یکشنبه، 1=دوشنبه، ...، 5=جمعه، 6=شنبه
const jWeekdays = ['یک\u200cشنبه', 'دوشنبه', 'سه\u200cشنبه', 'چهارشنبه', 'پنج\u200cشنبه', 'جمعه', 'شنبه'];
const analysisTime = jWeekdays[tehran.getUTCDay()] + ' ' + toFa(j.jd) + ' ' + jMonths[j.jm - 1] + ' ' + toFa(j.jy) +
  ' — ساعت ' + toFa(pad2(tehran.getUTCHours())) + ':' + toFa(pad2(tehran.getUTCMinutes()));

// ─── مرتب‌سازی اخبار از جدیدترین + حذف تکراری‌ها ───
function normalizeTitle(t) {
  return String(t || '')
    .replace(/[\u200c\u200f\u200e\s]+/g, ' ')
    .replace(/[«»"'?!.,:؛،()[\]{}\-–—_\/]/g, '')
    .trim();
}

const dated = items.map((i) => {
  const ts = Date.parse(i.json.isoDate || i.json.pubDate || '');
  return { item: i, ts: isNaN(ts) ? 0 : ts };
}).sort((a, b) => b.ts - a.ts);

const seen = new Set();
const lines = [];
for (const { item } of dated) {
  if (lines.length >= MAX_ITEMS) break;
  const title = String(item.json.title || '').replace(/\s+/g, ' ').trim();
  if (!title) continue;
  const key = normalizeTitle(title).slice(0, 45);
  if (seen.has(key)) continue;
  seen.add(key);
  const snippet = String(item.json.contentSnippet || item.json.content || '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 300);
  lines.push('• ' + title + (snippet ? '\n  ' + snippet : ''));
}

let news = lines.length ? lines.join('\n\n') : 'هیچ خبر مرتبطی یافت نشد.';
if (news.length > MAX_CHARS) news = news.slice(0, MAX_CHARS);

return [{ json: { news, analysisTime, count: lines.length } }];
